# Grid world hypothesis: action 1 moves the 5x5 striped block one cell-unit
# (five pixels) upward. The lower panel records the chosen action.

def step(state, action):
    nxt = state.copy()
    g = nxt.grid
    aid = int(action["id"])

    if aid == 1:
        # Locate a movable 5x5 block whose upper rows are color 12 and lower
        # rows color 9. Movement occurs in five-pixel tile increments.
        found = None
        h = len(g)
        w = len(g[0])
        for y in range(h - 4):
            for x in range(w - 4):
                ok = True
                for dy in range(5):
                    expected = 12 if dy < 2 else 9
                    for dx in range(5):
                        if g[y + dy][x + dx] != expected:
                            ok = False
                if ok:
                    found = (x, y)
                    break
            if found is not None:
                break
        if found is not None:
            x, y = found
            if y >= 5:
                for dy in range(5):
                    for dx in range(5):
                        g[y + dy][x + dx] = 3
                for dy in range(5):
                    c = 12 if dy < 2 else 9
                    for dx in range(5):
                        g[y - 5 + dy][x + dx] = c

        # Action display in the bottom control strip.
        if h > 62 and w > 13:
            g[61][13] = 3
            g[62][13] = 3

    return nxt


def is_goal(state):
    return state.state == "WIN" or state.levels_completed > 0

