# rows color 9. Actions 1 and 2 are observed vertical tile moves.
found = None
h = len(g)
w = len(g[0])
for y in range(h - 4):
    for x in range(w - 4):
        ok = True
        for sy in range(5):
            expected = 12 if sy < 2 else 9
            for sx in range(5):
                if g[y + sy][x + sx] != expected:
                    ok = False
        if ok:
            found = (x, y)
            break
    if found is not None:
        break

move_y = -5 if aid == 1 else (5 if aid == 2 else 0)
if found is not None and move_y != 0:
    x, y = found
    ny = y + move_y
    if 0 <= ny and ny + 4 < h:
        for sy in range(5):
            for sx in range(5):
                g[y + sy][x + sx] = 3
        for sy in range(5):
            c = 12 if sy < 2 else 9
            for sx in range(5):
                g[ny + sy][x + sx] = c

